import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { CheckCircle2, Eye, EyeOff, GraduationCap, Lock, Shield, ShoppingBag, User } from "lucide-react";
import { useAuth } from "./AuthContext";
import { useNotice } from "./NoticeContext";
import { decodeJwtPayload } from "./authJwt";
import { h } from "./h";
import { apiFetch } from "./api";
import { apiErrorMessage } from "./screensAuth";
import { Button, Field, InlineNotice, OtpCodeInput, TextInput } from "./ui";

function sessionRole(data) {
  const r = data?.user?.role;
  if (r) return r;
  return decodeJwtPayload(data?.accessToken)?.role || "";
}

function AdminBrandingColumn() {
  return h(
    "div",
    {
      key: "brand",
      className:
        "relative flex min-h-[220px] flex-col justify-between overflow-hidden bg-[#0b1220] px-8 py-10 text-white lg:min-h-screen lg:w-1/2 lg:px-12 lg:py-14"
    },
    [
      h("div", {
        key: "dots-tl",
        className:
          "pointer-events-none absolute -left-8 -top-8 h-40 w-40 rounded-full bg-emerald-500/15 blur-2xl"
      }),
      h("div", {
        key: "dots-br",
        className:
          "pointer-events-none absolute -bottom-10 -right-10 h-48 w-48 rounded-full bg-emerald-400/10 blur-3xl"
      }),
      h("div", { key: "top", className: "relative z-10 flex items-center gap-3" }, [
        h(
          "div",
          {
            key: "ico",
            className:
              "flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br from-emerald-400 to-green-600 shadow-lg shadow-emerald-900/50"
          },
          h(ShoppingBag, { className: "h-6 w-6 text-white" })
        ),
        h("div", { key: "titles" }, [
          h("div", { key: "t1", className: "font-display text-lg font-bold tracking-tight" }, "CampusMarket"),
          h(
            "div",
            { key: "t2", className: "text-xs font-medium uppercase tracking-wider text-emerald-300/90" },
            "Admin Portal"
          )
        ])
      ]),
      h("div", { key: "mid", className: "relative z-10 mt-8 max-w-md lg:mt-0" }, [
        h("div", { key: "grad", className: "mb-2 flex items-center gap-2 text-emerald-400" }, [
          h(GraduationCap, { className: "h-5 w-5" }),
          h("span", { className: "text-sm font-semibold" }, "Staff only")
        ]),
        h("h1", { key: "h1", className: "font-display text-3xl font-bold leading-tight lg:text-4xl" }, "Admin Access Only"),
        h(
          "p",
          { key: "sub", className: "mt-4 text-sm leading-relaxed text-slate-300 lg:text-base" },
          "Secure login for administrators to manage the CampusMarket platform."
        )
      ]),
      h(
        "div",
        {
          key: "illus",
          className: "relative z-10 mt-10 hidden items-end justify-center gap-4 lg:flex lg:min-h-[200px]"
        },
        [
          h(
            "div",
            {
              key: "lap",
              className:
                "relative rounded-2xl border border-white/10 bg-slate-800/50 p-4 shadow-2xl backdrop-blur-sm"
            },
            [
              h("div", { className: "mb-2 h-2 w-32 rounded bg-white/20" }),
              h("div", { className: "mb-2 h-2 w-24 rounded bg-white/10" }),
              h("div", { className: "h-20 w-40 rounded-lg bg-emerald-500/20" })
            ]
          ),
          h(
            "div",
            {
              key: "shield",
              className:
                "-ml-6 flex h-28 w-28 items-center justify-center rounded-3xl border-4 border-emerald-400/80 bg-emerald-500/20 shadow-xl"
            },
            h(Shield, { className: "h-14 w-14 text-emerald-300" })
          )
        ]
      )
    ]
  );
}

export function AdminLoginPage() {
  const nav = useNavigate();
  const { login, logout, accessToken, user, loading } = useAuth();
  const { toast } = useNotice();
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [show, setShow] = useState(false);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (!loading && accessToken && user?.role === "admin") {
      nav("/admin", { replace: true });
    }
  }, [loading, accessToken, user, nav]);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setBusy(true);
    try {
      const data = await login(identifier.trim(), password);
      if (data?.needsOtp) {
        nav("/admin/login-otp", {
          replace: true,
          state: { email: data.email || identifier.trim().toLowerCase(), from: "/admin" }
        });
        return;
      }
      if (sessionRole(data) !== "admin") {
        await logout();
        setErr("This portal is for platform administrators only. Use the main sign-in for buyer or vendor accounts.");
        return;
      }
      toast("Welcome — admin dashboard", { variant: "success" });
      nav("/admin", { replace: true });
    } catch (ex) {
      const msg = apiErrorMessage(ex, "We couldn’t sign you in. Check your email and password.");
      if (ex.status === 403 && /verify/i.test(msg)) {
        setErr("This account must verify email on the main site first, or contact support.");
      } else {
        setErr(msg);
      }
    } finally {
      setBusy(false);
    }
  };

  return h("div", { className: "min-h-screen bg-slate-100 dark:bg-night-950" }, [
    h(
      "div",
      { key: "shell", className: "flex min-h-screen flex-col lg:flex-row" },
      [
        h(AdminBrandingColumn, { key: "left" }),
        h(
          "div",
          {
            key: "right",
            className:
              "flex flex-1 items-center justify-center px-4 py-10 sm:px-8 lg:w-1/2 lg:py-14 dark:bg-night-950"
          },
          h(
            "div",
            {
              className:
                "w-full max-w-md rounded-3xl border border-slate-200/80 bg-white p-8 shadow-xl dark:border-white/10 dark:bg-night-900"
            },
            [
              h("div", { key: "hdr", className: "mb-6 text-center" }, [
                h(
                  "div",
                  {
                    key: "shico",
                    className:
                      "mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-400"
                  },
                  h(Shield, { className: "h-7 w-7" })
                ),
                h("h2", { key: "t", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Admin Login"),
                h(
                  "p",
                  { key: "s", className: "mt-2 text-sm text-slate-600 dark:text-slate-400" },
                  "Enter your credentials to access the admin dashboard."
                )
              ]),
              h(
                "form",
                { key: "frm", className: "space-y-4", onSubmit },
                [
                  h(Field, { key: "em", label: "Email Address" }, h("div", { className: "relative" }, [
                    h(User, {
                      className:
                        "pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"
                    }),
                    h(TextInput, {
                      type: "email",
                      autoComplete: "username",
                      value: identifier,
                      onChange: (e) => setIdentifier(e.target.value),
                      placeholder: "Enter admin email",
                      className: "pl-10",
                      required: true
                    })
                  ])),
                  h(Field, { key: "pw", label: "Password" }, h("div", { className: "relative" }, [
                    h(Lock, {
                      className:
                        "pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"
                    }),
                    h(TextInput, {
                      type: show ? "text" : "password",
                      autoComplete: "current-password",
                      value: password,
                      onChange: (e) => setPassword(e.target.value),
                      placeholder: "Enter password",
                      className: "pr-12 pl-10",
                      required: true
                    }),
                    h(
                      "button",
                      {
                        key: "eye",
                        type: "button",
                        className:
                          "tap-target absolute right-1 top-1/2 -translate-y-1/2 rounded-xl p-2 text-slate-500 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-white/10",
                        onClick: () => setShow((s) => !s)
                      },
                      show ? h(EyeOff, { className: "h-5 w-5" }) : h(Eye, { className: "h-5 w-5" })
                    )
                  ])),
                  err ? h(InlineNotice, { key: "err", variant: "error", onDismiss: () => setErr("") }, err) : null,
                  h(
                    Button,
                    {
                      key: "go",
                      type: "submit",
                      className: "w-full !bg-emerald-600 !text-white hover:!bg-emerald-700 dark:!bg-emerald-600",
                      loading: busy
                    },
                    "Login to Dashboard"
                  )
                ]
              ),
              h("div", { key: "div", className: "relative my-6" }, [
                h("div", { className: "absolute inset-0 flex items-center" }, h("div", { className: "w-full border-t border-slate-200 dark:border-white/10" })),
                h(
                  "div",
                  { className: "relative flex justify-center text-xs font-semibold uppercase tracking-wide" },
                  h(
                    "span",
                    {
                      className:
                        "inline-flex items-center gap-1.5 bg-white px-3 text-emerald-600 dark:bg-night-900 dark:text-emerald-400"
                    },
                    [h(CheckCircle2, { className: "h-3.5 w-3.5" }), "Secure"]
                  )
                )
              ]),
              h(
                "div",
                {
                  key: "note",
                  className:
                    "flex gap-3 rounded-2xl border border-emerald-200/80 bg-emerald-50/80 p-4 text-sm text-emerald-900 dark:border-emerald-500/30 dark:bg-emerald-500/10 dark:text-emerald-100/90"
                },
                [
                  h(Lock, { className: "mt-0.5 h-4 w-4 shrink-0" }),
                  h("p", { key: "txt" }, [
                    h("span", { className: "font-semibold" }, "Restricted Access"),
                    " — This area is for authorized administrators only. There is no self-service registration."
                  ])
                ]
              ),
              h(
                "p",
                { key: "back", className: "mt-6 text-center text-sm text-slate-500 dark:text-slate-400" },
                h(Link, { to: "/", className: "text-emerald-600 hover:underline dark:text-emerald-400" }, "← Back to CampusMarket")
              )
            ]
          )
        )
      ]
    )
  ]);
}

export function AdminLoginOtpPage() {
  const nav = useNavigate();
  const location = useLocation();
  const { verifyLoginOtp, logout, accessToken, user, loading } = useAuth();
  const { toast } = useNotice();
  const email = String(location.state?.email || "").trim().toLowerCase();
  const [otp, setOtp] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const [resendLoading, setResendLoading] = useState(false);
  const [resendMsg, setResendMsg] = useState("");

  useEffect(() => {
    if (!loading && accessToken && user?.role === "admin") {
      nav("/admin", { replace: true });
    }
  }, [loading, accessToken, user, nav]);

  useEffect(() => {
    if (!email) nav("/admin/login", { replace: true });
  }, [email, nav]);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setResendMsg("");
    if (otp.length !== 6) {
      setErr("Enter the full 6-digit code.");
      return;
    }
    setBusy(true);
    try {
      const data = await verifyLoginOtp(email, otp);
      if (sessionRole(data) !== "admin") {
        await logout();
        setErr("This portal is for platform administrators only.");
        return;
      }
      toast("Welcome — admin dashboard", { variant: "success" });
      nav("/admin", { replace: true });
    } catch (ex) {
      setErr(apiErrorMessage(ex, "That code did not work. Try again or request a new code."));
    } finally {
      setBusy(false);
    }
  };

  const onResend = async (e) => {
    e.preventDefault();
    setErr("");
    setResendMsg("");
    if (!password) {
      setErr("Enter your password to send a new code.");
      return;
    }
    setResendLoading(true);
    try {
      await apiFetch("/api/auth/resend-login-otp", {
        method: "POST",
        json: { identifier: email, password }
      });
      setResendMsg("A new code was sent to your email.");
      setOtp("");
    } catch (ex) {
      setErr(apiErrorMessage(ex, "Could not resend. Check your password and try again."));
    } finally {
      setResendLoading(false);
    }
  };

  if (!email) return null;

  return h("div", { className: "min-h-screen bg-slate-100 dark:bg-night-950" }, [
    h(
      "div",
      { key: "shell", className: "flex min-h-screen flex-col lg:flex-row" },
      [
        h(AdminBrandingColumn, { key: "left" }),
        h(
          "div",
          {
            key: "right",
            className:
              "flex flex-1 items-center justify-center px-4 py-10 sm:px-8 lg:w-1/2 lg:py-14 dark:bg-night-950"
          },
          h(
            "div",
            {
              className:
                "w-full max-w-md rounded-3xl border border-slate-200/80 bg-white p-8 shadow-xl dark:border-white/10 dark:bg-night-900"
            },
            [
              h("div", { key: "hdr", className: "mb-6 text-center" }, [
                h("h2", { key: "t", className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Verify sign-in"),
                h(
                  "p",
                  { key: "s", className: "mt-2 text-sm text-slate-600 dark:text-slate-400" },
                  `We sent a 6-digit code to ${email}.`
                )
              ]),
              h(
                "form",
                { key: "frm", className: "space-y-4", onSubmit },
                [
                  h(
                    Field,
                    { key: "otp", label: "Sign-in code" },
                    h(OtpCodeInput, {
                      value: otp,
                      onChange: setOtp,
                      autoFocus: true,
                      "aria-invalid": err && otp.length < 6 ? true : undefined
                    })
                  ),
                  err ? h(InlineNotice, { key: "err", variant: "error", onDismiss: () => setErr("") }, err) : null,
                  resendMsg
                    ? h(InlineNotice, { key: "ok", variant: "success", size: "sm", onDismiss: () => setResendMsg("") }, resendMsg)
                    : null,
                  h(
                    Button,
                    {
                      key: "go",
                      type: "submit",
                      className: "w-full !bg-emerald-600 !text-white hover:!bg-emerald-700",
                      loading: busy
                    },
                    "Continue to dashboard"
                  ),
                  h("div", { key: "resend", className: "rounded-2xl border border-slate-200/80 bg-slate-50 p-4 dark:border-white/10 dark:bg-white/5" }, [
                    h("p", { key: "r1", className: "text-xs font-semibold uppercase tracking-wide text-slate-500" }, "Need a new code?"),
                    h(Field, { key: "pw", label: "Password" }, h("div", { className: "relative" }, [
                      h(TextInput, {
                        type: showPw ? "text" : "password",
                        autoComplete: "current-password",
                        value: password,
                        onChange: (e) => setPassword(e.target.value),
                        className: "pr-12",
                        placeholder: "••••••••"
                      }),
                      h(
                        "button",
                        {
                          key: "eye",
                          type: "button",
                          className:
                            "tap-target absolute right-1 top-1/2 -translate-y-1/2 rounded-xl p-2 text-slate-500 hover:bg-white/40 dark:hover:bg-white/10",
                          onClick: () => setShowPw((s) => !s)
                        },
                        showPw ? h(EyeOff, { className: "h-5 w-5" }) : h(Eye, { className: "h-5 w-5" })
                      )
                    ])),
                    h(
                      Button,
                      {
                        key: "rs",
                        type: "button",
                        variant: "subtle",
                        className: "mt-3 w-full",
                        loading: resendLoading,
                        onClick: onResend
                      },
                      "Resend code"
                    )
                  ]),
                  h(
                    Link,
                    {
                      key: "back",
                      to: "/admin/login",
                      className: "block text-center text-sm text-emerald-600 hover:underline dark:text-emerald-400"
                    },
                    "← Back to admin sign in"
                  )
                ]
              )
            ]
          )
        )
      ]
    )
  ]);
}
